// Environmental puzzles. Each generator is deterministic (seeded) and every
// generated puzzle is solvable – tests verify this with the included solvers.
// The 3D layer renders the state and calls the action functions; all clues
// (dots on pillars, murals, glowing leaves) are part of the generated data.
import { createRng } from '../core/rng.js';

const DIRS = { n: [0, -1], s: [0, 1], w: [-1, 0], e: [1, 0] };
const key = (x, y) => x + ',' + y;

// ---------------------------------------------------------------------------
// Push blocks onto plates (Sokoban-like). Generated by reverse play (pulling
// blocks away from plates), which guarantees a solution exists.
// ---------------------------------------------------------------------------
function genPush(rng, { w = 7, h = 7, blocks = 2, slide = false }) {
  for (let attempt = 0; attempt < (slide ? 900 : 400); attempt++) {
    const walls = new Set();
    for (let x = 0; x < w; x++) { walls.add(key(x, -1)); walls.add(key(x, h)); }
    for (let y = 0; y < h; y++) { walls.add(key(-1, y)); walls.add(key(w, y)); }
    const inner = [];
    for (let y = 1; y < h - 1; y++) for (let x = 1; x < w - 1; x++) inner.push([x, y]);
    const pillars = rng.shuffle(inner).slice(0, Math.floor(w * h * (slide ? 0.08 : 0.06)));
    for (const [x, y] of pillars) walls.add(key(x, y));
    const free = [];
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (!walls.has(key(x, y))) free.push([x, y]);
    const pick = rng.shuffle(free);
    const plates = pick.slice(0, blocks).map(p => [...p]);
    const start = { blocks: plates.map(p => [...p]), player: [...pick[blocks]] };
    const state = { w, h, walls, plates, blocks: start.blocks.map(b => [...b]), player: [...start.player], slide };
    if (slide) {
      // sliding: random scramble then verify solvable with BFS
      const scr = { ...state, blocks: rng.shuffle(free.filter(f => !plates.some(p => p[0] === f[0] && p[1] === f[1]))).slice(0, blocks).map(p => [...p]) };
      const occupied = new Set(scr.blocks.map(b => key(...b)));
      const pfree = free.filter(f => !occupied.has(key(...f)));
      scr.player = [...pfree[Math.floor(rng.next() * pfree.length)]];
      const sol = solvePush(scr, 18);
      if (sol && sol.length >= 3) return finalizePush(scr);
      continue;
    }
    // reverse play: player pulls blocks
    let pulls = 0;
    for (let step = 0; step < 220; step++) {
      const d = rng.pick(Object.keys(DIRS));
      const [dx, dy] = DIRS[d];
      const [px, py] = state.player;
      const nx = px + dx, ny = py + dy;
      if (blocked(state, nx, ny)) continue;
      const bi = state.blocks.findIndex(b => b[0] === px - dx && b[1] === py - dy);
      state.player = [nx, ny];
      if (bi >= 0 && rng.next() < 0.7) { state.blocks[bi] = [px, py]; pulls++; }
    }
    const onPlate = state.blocks.filter(b => plates.some(p => p[0] === b[0] && p[1] === b[1])).length;
    // Reverse play guarantees solvability, so no search is needed here.
    if (pulls < 6 || onPlate > 0) continue;
    const dist = state.blocks.reduce((a, b, i) => a + Math.abs(b[0] - plates[i][0]) + Math.abs(b[1] - plates[i][1]), 0);
    if (dist >= 4) return finalizePush(state);
  }
  // fallback trivial layout (still solvable)
  const walls = new Set();
  for (let x = 0; x < 5; x++) { walls.add(key(x, -1)); walls.add(key(x, 5)); }
  for (let y = 0; y < 5; y++) { walls.add(key(-1, y)); walls.add(key(5, y)); }
  return finalizePush({ w: 5, h: 5, walls, plates: [[4, 2]], blocks: [[2, 2]], player: [1, 2], slide });
}
function finalizePush(s) {
  return { kind: s.slide ? 'ice' : 'plates', w: s.w, h: s.h, walls: [...s.walls], plates: s.plates, blocks: s.blocks, player: s.player, start: { blocks: s.blocks.map(b => [...b]), player: [...s.player] }, moves: 0 };
}
function blocked(s, x, y) {
  const walls = s.walls instanceof Set ? s.walls : (s._wallSet ||= new Set(s.walls));
  return walls.has(key(x, y)) || x < 0 || y < 0 || x >= s.w || y >= s.h;
}
function blockAt(s, x, y) { return s.blocks.findIndex(b => b[0] === x && b[1] === y); }

// Push the block at index `bi` in direction d. Returns true when it moved.
export function pushBlock(s, bi, d) {
  const [dx, dy] = DIRS[d];
  const b = s.blocks[bi];
  if (!b) return false;
  let [x, y] = b;
  const free = (nx, ny) => !blocked(s, nx, ny) && blockAt(s, nx, ny) < 0;
  if (!free(x + dx, y + dy)) return false;
  if (s.kind === 'ice') { while (free(x + dx, y + dy)) { x += dx; y += dy; } }
  else { x += dx; y += dy; }
  s.player = [b[0], b[1]];
  s.blocks[bi] = [x, y];
  s.moves++;
  return true;
}
export function resetPush(s) { s.blocks = s.start.blocks.map(b => [...b]); s.player = [...s.start.player]; s.moves = 0; }
export function pushSolved(s) { return s.plates.every(p => s.blocks.some(b => b[0] === p[0] && b[1] === p[1])); }

// BFS solver over (player region, blocks). Player walks freely between pushes.
export function solvePush(s, maxPushes = 40) {
  const W = s.w, H = s.h, N = W * H, slide = (s.kind || (s.slide ? 'ice' : 'plates')) === 'ice';
  const wallSet = s.walls instanceof Set ? s.walls : new Set(s.walls);
  const wall = new Uint8Array(N);
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (wallSet.has(key(x, y))) wall[y * W + x] = 1;
  const plateIdx = s.plates.map(([x, y]) => y * W + x);
  const D = [[0, -1], [0, 1], [-1, 0], [1, 0]], DN = ['n', 's', 'w', 'e'];
  const inside = (x, y) => x >= 0 && y >= 0 && x < W && y < H;
  const occ = new Uint8Array(N), seenR = new Int32Array(N);
  let stamp = 0;
  const reach = (p, bl) => {
    stamp++;
    occ.fill(0); for (const b of bl) occ[b] = 1;
    const q = [p]; seenR[p] = stamp; let min = p;
    for (let qi = 0; qi < q.length; qi++) {
      const c = q[qi], x = c % W, y = (c / W) | 0;
      for (const [dx, dy] of D) {
        const nx = x + dx, ny = y + dy; if (!inside(nx, ny)) continue;
        const n = ny * W + nx; if (wall[n] || occ[n] || seenR[n] === stamp) continue;
        seenR[n] = stamp; q.push(n); if (n < min) min = n;
      }
    }
    return min;
  };
  const startBl = s.blocks.map(([x, y]) => y * W + x);
  const startP = reach(s.player[1] * W + s.player[0], startBl);
  const enc = (p, bl) => p + '|' + bl.slice().sort((a, b) => a - b).join(',');
  const seen = new Set([enc(startP, startBl)]);
  let q = [{ p: startP, bl: startBl, path: [] }];
  for (let depth = 0; depth <= maxPushes && q.length; depth++) {
    const next = [];
    for (const node of q) {
      if (plateIdx.every(pi => node.bl.includes(pi))) return node.path;
      reach(node.p, node.bl);
      const mask = new Uint8Array(N);
      for (let i = 0; i < N; i++) if (seenR[i] === stamp) mask[i] = 1;
      for (let bi = 0; bi < node.bl.length; bi++) {
        const b = node.bl[bi], bx = b % W, by = (b / W) | 0;
        for (let d = 0; d < 4; d++) {
          const [dx, dy] = D[d];
          const px = bx - dx, py = by - dy;
          if (!inside(px, py) || !mask[py * W + px]) continue;
          let x = bx, y = by;
          const free = (nx, ny) => inside(nx, ny) && !wall[ny * W + nx] && !node.bl.includes(ny * W + nx);
          if (!free(x + dx, y + dy)) continue;
          if (slide) { while (free(x + dx, y + dy)) { x += dx; y += dy; } } else { x += dx; y += dy; }
          const nbl = node.bl.slice(); nbl[bi] = y * W + x;
          const np = reach(b, nbl);
          const k = enc(np, nbl);
          if (seen.has(k)) continue;
          seen.add(k);
          next.push({ p: np, bl: nbl, path: [...node.path, { block: bi, dir: DN[d] }] });
        }
      }
    }
    q = next;
    if (seen.size > 200000) break;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Lanterns: toggling one lantern flips itself and its neighbours.
// ---------------------------------------------------------------------------
function genSwitches(rng, { n = 5, ring = false }) {
  const lit = Array(n).fill(true);
  const presses = new Set();
  const count = Math.max(2, Math.floor(n / 2));
  while (presses.size < count) presses.add(rng.int(0, n - 1));
  const s = { kind: 'switches', n, ring, lit, solution: [...presses] };
  for (const i of presses) toggle(s, i, true);
  if (s.lit.every(Boolean)) toggle(s, 0, true), s.solution.push(0);
  return s;
}
function toggle(s, i, silent) {
  for (const j of [i - 1, i, i + 1]) {
    let k = j;
    if (s.ring) k = (j + s.n) % s.n;
    if (k < 0 || k >= s.n) continue;
    s.lit[k] = !s.lit[k];
  }
  if (!silent) s.moves = (s.moves || 0) + 1;
}
export function pressSwitch(s, i) { toggle(s, i); return s.lit.every(Boolean); }
export function switchesSolved(s) { return s.lit.every(Boolean); }
export function solveSwitches(s) {
  for (let mask = 0; mask < (1 << s.n); mask++) {
    const sim = { ...s, lit: s.lit.slice() };
    const presses = [];
    for (let i = 0; i < s.n; i++) if (mask & (1 << i)) { toggle(sim, i, true); presses.push(i); }
    if (sim.lit.every(Boolean)) return presses;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Order: step on plates in ascending number of dots shown on nearby pillars.
// ---------------------------------------------------------------------------
function genOrder(rng, { n = 4 }) {
  const dots = rng.shuffle(Array.from({ length: n }, (_, i) => i + 1));
  return { kind: 'order', n, dots, progress: 0, solved: false };
}
export function stepOrder(s, i) {
  const expected = s.progress + 1;
  if (s.dots[i] === expected) { s.progress++; if (s.progress >= s.n) s.solved = true; return { ok: true, solved: s.solved }; }
  s.progress = 0;
  return { ok: false, solved: false };
}
export function solveOrder(s) { return s.dots.map((d, i) => [d, i]).sort((a, b) => a[0] - b[0]).map(x => x[1]); }

// ---------------------------------------------------------------------------
// Runes: rotate stones until each shows the symbol painted on its mural.
// ---------------------------------------------------------------------------
export const RUNE_SYMBOLS = ['Sonne', 'Welle', 'Blatt', 'Stern'];
function genRunes(rng, { n = 3 }) {
  const target = Array.from({ length: n }, () => rng.int(0, 3));
  let current = target.map(t => (t + rng.int(1, 3)) % 4);
  return { kind: 'runes', n, target, current, solved: false };
}
export function rotateRune(s, i) { s.current[i] = (s.current[i] + 1) % 4; s.solved = s.current.every((c, j) => c === s.target[j]); return s.solved; }
export function solveRunes(s) { return s.current.map((c, i) => (s.target[i] - c + 4) % 4); }

// ---------------------------------------------------------------------------
// Crystals: rotate mirrors so the light beam reaches the target crystal.
// Grid cells: mirrors with orientation 0 = '/', 1 = '\'.
// ---------------------------------------------------------------------------
function genCrystals(rng, { w = 6, h = 6, bends = 3 }) {
  for (let attempt = 0; attempt < 300; attempt++) {
    const mirrors = [];
    let x = 0, y = rng.int(1, h - 2), dir = 'e';
    const source = { x: -1, y, dir: 'e' };
    const path = new Set([key(x, y)]);
    let ok = true;
    for (let bend = 0; bend < bends; bend++) {
      const len = rng.int(1, 3);
      for (let i = 0; i < len; i++) {
        const [dx, dy] = DIRS[dir];
        x += dx; y += dy;
        if (x < 0 || y < 0 || x >= w || y >= h || path.has(key(x, y))) { ok = false; break; }
        path.add(key(x, y));
      }
      if (!ok) break;
      const turns = dir === 'e' || dir === 'w' ? ['n', 's'] : ['e', 'w'];
      const nd = rng.pick(turns);
      // orientation that reflects dir->nd
      const o = reflectOrientation(dir, nd);
      mirrors.push({ x, y, o, solution: o });
      dir = nd;
    }
    if (!ok) continue;
    // final straight run to the target at the border
    let tx = x, ty = y;
    for (let i = 0; i < 12; i++) {
      const [dx, dy] = DIRS[dir];
      const nx = tx + dx, ny = ty + dy;
      if (nx < 0 || ny < 0 || nx >= w || ny >= h) break;
      if (path.has(key(nx, ny))) { ok = false; break; }
      tx = nx; ty = ny; path.add(key(tx, ty));
    }
    if (!ok || (tx === x && ty === y)) continue;
    const target = { x: tx, y: ty };
    // decoys
    const decoys = [];
    for (let i = 0; i < 2; i++) {
      const dx = rng.int(0, w - 1), dy = rng.int(0, h - 1);
      if (!path.has(key(dx, dy)) && !mirrors.some(m => m.x === dx && m.y === dy)) decoys.push({ x: dx, y: dy, o: rng.int(0, 1), decoy: true });
    }
    const all = [...mirrors, ...decoys];
    const s = { kind: 'crystals', w, h, source, target, mirrors: all, solved: false };
    for (const m of mirrors) m.o = 1 - m.o; // scramble path mirrors
    if (traceBeam(s).hit) continue;
    return s;
  }
  return { kind: 'crystals', w: 3, h: 3, source: { x: -1, y: 1, dir: 'e' }, target: { x: 1, y: 0 }, mirrors: [{ x: 1, y: 1, o: 1, solution: 0 }], solved: false };
}
function reflectOrientation(from, to) {
  // '/' (0): e->n, n->e, w->s, s->w ; '\' (1): e->s, s->e, w->n, n->w
  const slash = { e: 'n', n: 'e', w: 's', s: 'w' };
  return slash[from] === to ? 0 : 1;
}
function reflect(dir, o) {
  const slash = { e: 'n', n: 'e', w: 's', s: 'w' }, back = { e: 's', s: 'e', w: 'n', n: 'w' };
  return o === 0 ? slash[dir] : back[dir];
}
export function traceBeam(s) {
  let x = s.source.x, y = s.source.y, dir = s.source.dir;
  const cells = [];
  for (let i = 0; i < 100; i++) {
    const [dx, dy] = DIRS[dir];
    x += dx; y += dy;
    if (x < 0 || y < 0 || x >= s.w || y >= s.h) return { hit: false, cells, exit: { x, y } };
    cells.push({ x, y, dir });
    if (x === s.target.x && y === s.target.y) return { hit: true, cells };
    const m = s.mirrors.find(m => m.x === x && m.y === y);
    if (m) dir = reflect(dir, m.o);
  }
  return { hit: false, cells };
}
export function rotateMirror(s, i) { s.mirrors[i].o = 1 - s.mirrors[i].o; s.solved = traceBeam(s).hit; return s.solved; }
export function solveCrystals(s) {
  const n = s.mirrors.length;
  for (let mask = 0; mask < (1 << n); mask++) {
    const sim = { ...s, mirrors: s.mirrors.map((m, i) => ({ ...m, o: (mask & (1 << i)) ? 1 - m.o : m.o })) };
    if (traceBeam(sim).hit) return s.mirrors.map((m, i) => (mask & (1 << i)) ? i : -1).filter(i => i >= 0);
  }
  return null;
}

// ---------------------------------------------------------------------------
// Maze: perfect maze with glowing leaves marking junctions on the true path.
// ---------------------------------------------------------------------------
function genMaze(rng, { w = 7, h = 7 }) {
  const walls = {}; // cell -> {n,e,s,w}
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) walls[key(x, y)] = { n: true, e: true, s: true, w: true };
  const opp = { n: 's', s: 'n', e: 'w', w: 'e' };
  const stack = [[0, h - 1]], seen = new Set([key(0, h - 1)]);
  while (stack.length) {
    const [x, y] = stack[stack.length - 1];
    const opts = rng.shuffle(Object.entries(DIRS)).filter(([, [dx, dy]]) => {
      const nx = x + dx, ny = y + dy;
      return nx >= 0 && ny >= 0 && nx < w && ny < h && !seen.has(key(nx, ny));
    });
    if (!opts.length) { stack.pop(); continue; }
    const [d, [dx, dy]] = opts[0];
    walls[key(x, y)][d] = false;
    walls[key(x + dx, y + dy)][opp[d]] = false;
    seen.add(key(x + dx, y + dy));
    stack.push([x + dx, y + dy]);
  }
  const s = { kind: 'maze', w, h, walls, start: [0, h - 1], goal: [w - 1, 0], solved: false };
  const path = solveMaze(s);
  // glow markers at every junction (cells with >2 openings) on the path
  s.glow = path.filter(([x, y]) => Object.values(walls[key(x, y)]).filter(v => !v).length > 2).map(p => [...p]);
  s.path = path;
  return s;
}
export function solveMaze(s) {
  const start = key(...s.start), goal = key(...s.goal);
  const prev = { [start]: null }, q = [s.start];
  while (q.length) {
    const [x, y] = q.shift();
    if (key(x, y) === goal) break;
    for (const [d, [dx, dy]] of Object.entries(DIRS)) {
      if (s.walls[key(x, y)][d]) continue;
      const k = key(x + dx, y + dy);
      if (k in prev) continue;
      prev[k] = key(x, y); q.push([x + dx, y + dy]);
    }
  }
  if (!(goal in prev)) return null;
  const path = [];
  for (let k = goal; k; k = prev[k]) path.unshift(k.split(',').map(Number));
  return path;
}

// ---------------------------------------------------------------------------
export function generatePuzzle(kind, seed, difficulty = 0) {
  const rng = createRng('puzzle:' + kind + ':' + seed);
  const d = Math.max(0, Math.min(3, difficulty));
  switch (kind) {
    case 'plates': return genPush(rng, { w: 6 + Math.min(2, d), h: 6 + Math.min(2, d), blocks: d >= 2 ? 3 : 2 });
    case 'ice': return genPush(rng, { w: 7, h: 7, blocks: d >= 2 ? 2 : 1, slide: true });
    case 'switches': return genSwitches(rng, { n: 5 + Math.min(2, d), ring: d >= 2 });
    case 'order': return genOrder(rng, { n: 4 + Math.min(2, d) });
    case 'runes': return genRunes(rng, { n: 3 + Math.min(1, d) });
    case 'crystals': return genCrystals(rng, { w: 6, h: 6, bends: 2 + Math.min(2, d) });
    case 'maze': return genMaze(rng, { w: 6 + d, h: 6 + d });
    default: throw new Error('Unknown puzzle kind ' + kind);
  }
}

export function isSolved(p) {
  switch (p.kind) {
    case 'plates': case 'ice': return pushSolved(p);
    case 'switches': return switchesSolved(p);
    default: return !!p.solved;
  }
}

// Returns a list of abstract actions that solve the puzzle from its state.
export function solve(p) {
  switch (p.kind) {
    case 'plates': case 'ice': return solvePush(p, 60);
    case 'switches': return solveSwitches(p);
    case 'order': return solveOrder(p);
    case 'runes': return solveRunes(p);
    case 'crystals': return solveCrystals(p);
    case 'maze': return solveMaze(p);
  }
  return null;
}

export const PUZZLE_TEXT = {
  plates: 'Schiebe alle Steine auf die leuchtenden Bodenplatten. Der Hebel setzt das Rätsel zurück.',
  ice: 'Eisblöcke rutschen, bis sie anstoßen. Bringe sie auf die Frostplatten. Der Hebel setzt zurück.',
  switches: 'Jede Laterne schaltet auch ihre Nachbarn. Bringe alle Laternen zum Leuchten.',
  order: 'Betritt die Platten in der Reihenfolge der Punkte auf den Säulen – von wenigen zu vielen.',
  runes: 'Drehe jeden Runenstein, bis er das Zeichen auf seinem Wandbild zeigt.',
  crystals: 'Drehe die Spiegel, bis der Lichtstrahl den Zielkristall trifft.',
  maze: 'Finde den Weg durch das Labyrinth. Leuchtende Blätter markieren Abzweigungen des richtigen Pfades.'
};
